      "path": "src/render.js",
      "content": "// Draft → single-file HTML. Pipeline: parse → STE lint → render panels (markdown / components / raw) → apply template → inline CSS and runtime.\n\nimport { parseDocLoose, ParseError, raiseAll, applyOverrides, CHOICES } from './parse.js';\nimport { md, collectHtmlNotes } from './markdown.js';\nimport { COMPONENTS, RAW_LANGS, ComponentError } from './components/index.js';\nimport { TEMPLATES } from './templates/index.js';\nimport { pageCss } from './themes/index.js';\nimport { BUILTIN, AUTO, pickTheme } from './themes/registry.js';\nimport { lintDoc } from './lint/ste.js';\nimport { esc } from './svg/text.js';\nimport { scaleSvgBoxes } from './svg/shapes.js';\nimport { SCALE } from './themes/type-scale.js';\nimport { VERSION, RUNTIME_JS, DELTA_JS, UPDATE_JS, CLOSE_AFTER_JS } from './assets.js';\nimport { rootTag, rootCarrierAttrs, sourceTag } from './page.js';\nimport { resolveLanguage } from './language.js';\nimport { inlineImages, remoteImages, ImageError, IMAGE_EXAMPLE } from './images.js';\nimport { renderCode, CodeError } from './code.js';\nimport { isolateLtrRuns } from './bidi.js';\nimport { hasMath } from './math.js';\nimport { cspMeta } from './csp.js';\n\n\nexport class RenderError extends Error {\n  constructor(message, { line, component, example } = {}) {\n    super(message);\n    this.name = 'RenderError';\n    this.line = line;\n    this.component = component;\n    this.example = example;\n  }\n}\n\nexport class LintError extends Error {\n  constructor(warnings) {\n    super(`STE check failed (style: strict): ${warnings.length} warning${warnings.length === 1 ? '' : 's'}`);\n    this.name = 'LintError';\n    this.warnings = warnings;\n  }\n}\n\n// themes: the theme set to pick from (the CLI passes the built-in themes plus the user's theme files).\n// previousLanguage: the language the page had before (a patched page keeps it unless the draft declares one).\n// baseDir: where relative image paths are read from; codeDir: where relative code paths are read from (the folder the agent works in).\n// knownImages / knownCode: what the page already embeds, the fallback when a file is gone.\n// update: { latest, current, command, highlights } from pageUpdate in src/update.js when a newer version is known; the page then has a new-version button.\n// closeAfter: the close_after_reply setting; the page then closes its tab a few seconds after the reply is copied (src/runtime/close-after-reply.js).\n// scale: the reader's text size (src/themes/type-scale.js); 1 is the default, so it adds nothing to the page.\nexport function renderDoc(source, overrides = {}, defaults = {}, { themes = BUILTIN, previousLanguage, baseDir, codeDir, knownImages, knownCode, update, closeAfter = false, scale = 1 } = {}) {\n  const choices = { theme: themes.choices('page') };\n  const { doc: parsed, errors } = parseDocLoose(source, { defaults, choices });\n  const meta = applyOverrides(parsed.meta, overrides, { ...CHOICES, ...choices });\n  if (meta.template === 'video') throw new ParseError('template: video is a video draft; render it with am video', 0);\n  const problem = themes.problem(meta.theme, 'page');\n  if (problem) throw new ParseError(problem, 0);\n  // theme: auto becomes a real theme here, so the page, the summary and later patches name the theme that was used.\n  const doc = { ...parsed, meta: meta.theme === AUTO ? { ...meta, theme: pickTheme({ scope: 'page', template: meta.template, visuals: hasVisuals(parsed) }) } : meta };\n\n  const language = resolveLanguage({ declared: doc.meta.lang, previous: previousLanguage, text: source });\n  const warnings = doc.meta.style === 'off' ? [] : lintDoc(doc, language);\n  if (doc.meta.style === 'strict' && warnings.length) {\n    raiseAll(errors); // the draft errors come first: they have to be fixed anyway\n    throw new LintError(warnings);\n  }\n\n  const stats = { panels: doc.panels.length, components: {}, code: [], codeWarnings: [], componentWarnings: [], htmlWarnings: [], mathWarnings: [] };\n  const ui = language.ui;\n  const ctx = { seq: 0, stats, errors, ui, dir: language.dir, scale, images: { baseDir, known: knownImages }, code: { baseDir: codeDir, known: knownCode } };\n  // A panel-only component in the intro is an error of its own, and the block renders nothing.\n  const loose = doc.intro.filter((b) => b.type === 'fence' && COMPONENTS.get(b.lang)?.panelOnly);\n  for (const b of loose) {\n    errors.push(new RenderError(`${b.lang} belongs in a panel: put it under the ## heading of the panel the answer changes`, { line: b.line, component: b.lang, example: COMPONENTS.get(b.lang).example }));\n  }\n  const introHtml = renderBlocks(doc.intro.filter((b) => !loose.includes(b)), ctx);\n  const panels = doc.panels.map((p) => ({ ...p, html: renderBlocks(p.blocks, ctx) }));\n  raiseAll(errors);\n  const page = TEMPLATES[doc.meta.template]({ meta: doc.meta, introHtml, panels, ui, language });\n  // A right-to-left page isolates each run of text with no right-to-left letter as left to right (src/bidi.js).\n  const body = language.dir === 'rtl' ? isolateLtrRuns(page) : page;\n  const html = shell({ meta: doc.meta, language, body, source, embedded: themes.embedFor(doc.meta.theme, 'page'), update, closeAfter, scale });\n  return { html, warnings, stats, meta: doc.meta, language };\n}\n\n// A diagram, another component or a raw html / svg block anywhere in the draft.\nfunction hasVisuals({ intro, panels }) {\n  return [...intro, ...panels.flatMap((p) => p.blocks)].some((b) => b.type === 'fence' && (COMPONENTS.has(b.lang) || RAW_LANGS.has(b.lang)));\n}\n\n// ctx.errors: an array that collects the RenderError of each block, so one run finds every broken block; a failing block renders\n// nothing and the next one goes on. Without it the first error throws. The caller throws what was collected (raiseAll in src/parse.js).\nexport function renderBlocks(blocks, ctx) {\n  return blocks.map((b) => {\n    if (!ctx.errors) return renderBlock(b, ctx);\n    try {\n      return renderBlock(b, ctx);\n    } catch (err) {\n      if (!(err instanceof RenderError)) throw err;\n      ctx.errors.push(err);\n      return '';\n    }\n  }).join('\\n');\n}\n\nfunction renderBlock(b, ctx) {\n  const { result, notes } = collectHtmlNotes(() => (b.type === 'md' ? `<div class=\"am-md\">${md(b.text)}</div>` : renderFence(b, ctx)), { math: !ctx.video });\n  noteHtml(b, notes.filter((n) => !n.math), ctx);\n  noteMath(b, notes.filter((n) => n.math), ctx);\n  const out = embedImages(b, result, ctx);\n  noteRemoteImages(b, out, ctx);\n  return out;\n}\n\n// Each remote image of one block, with the draft line that names it. The page blocks remote content (src/csp.js), so the image would be blank.\nfunction noteRemoteImages(block, html, ctx) {\n  if (!ctx.stats.htmlWarnings) return;\n  const lines = block.text.split('\\n');\n  const first = block.type === 'md' ? block.line : block.line + 1;\n  const used = new Map();\n  for (const ref of remoteImages(html)) {\n    const places = lines.flatMap((l, i) => (l.includes(ref) || l.includes(encodeURI(ref)) ? [i] : []));\n    const n = used.get(ref) ?? 0;\n    used.set(ref, n + 1);\n    const shown = ref.length > 80 ? `${ref.slice(0, 77)}...` : ref;\n    ctx.stats.htmlWarnings.push({ line: first + (places[Math.min(n, places.length - 1)] ?? 0), message: `remote image ${shown} does not load in the page; save the image and use its local path` });\n  }\n}\n\n// The raw-HTML notes of one block, each with the draft line of its tag. The nth note about the same tag points at its nth place in the block.\nfunction noteHtml(block, notes, ctx) {\n  if (!notes.length || !ctx.stats.htmlWarnings) return;\n  const lines = block.text.split('\\n');\n  const first = block.type === 'md' ? block.line : block.line + 1;\n  const used = new Map();\n  for (const { at, message } of notes) {\n    const tag = at.split('\\n')[0];\n    const places = lines.flatMap((l, i) => Array(l.split(tag).length - 1).fill(i));\n    const n = used.get(tag) ?? 0;\n    used.set(tag, n + 1);\n    ctx.stats.htmlWarnings.push({ line: first + (places[Math.min(n, places.length - 1)] ?? 0), message });\n  }\n}\n\n// The math notes of one block, each with the draft line of its formula. The nth note about the same formula points at its nth place in the block.\nfunction noteMath(block, notes, ctx) {\n  if (!notes.length || !ctx.stats.mathWarnings) return;\n  const first = block.type === 'md' ? block.line : block.line + 1;\n  const next = new Map();\n  for (const { at, message } of notes) {\n    const index = block.text.indexOf(at, next.get(at) ?? 0);\n    next.set(at, index + 1);\n    ctx.stats.mathWarnings.push({ line: first + (index < 0 ? 0 : block.text.slice(0, index).split('\\n').length - 1), message });\n  }\n}\n\n// Components that read their text as Markdown. Only there is ![a](b) an image the author meant; in raw html and in diagram text it is literal.\nconst MARKDOWN_FENCES = new Set(['callout', 'kv', 'tree', 'timeline']);\n\n// Local images in a block's html become data URIs; a missing or oversize file is reported at the line that names it.\nfunction embedImages(block, html, ctx) {\n  try {\n    return inlineImages(html, { ...ctx.images, checkText: block.type === 'md' || MARKDOWN_FENCES.has(block.lang) });\n  } catch (err) {\n    if (!(err instanceof ImageError)) throw err;\n    // The draft may write the path as decoded (a b.png) or percent-encoded (a%20b.png).\n    const idx = block.text.split('\\n').findIndex((l) => l.includes(err.ref) || l.includes(encodeURI(err.ref)));\n    const first = block.type === 'md' ? block.line : block.line + 1;\n    throw new RenderError(err.message, { line: first + Math.max(idx, 0), component: 'image', example: IMAGE_EXAMPLE });\n  }\n}\n\nfunction renderFence(block, ctx) {\n  const { lang, args, text, line } = block;\n  if (RAW_LANGS.has(lang)) return text;\n  const comp = COMPONENTS.get(lang);\n  if (!comp) return codeBlock(block, ctx);\n  if (comp.pageOnly && ctx.video) throw new RenderError(`${lang} works on a page only; a video cannot take answers`, { line, component: lang, example: comp.example });\n  ctx.stats.components[lang] = (ctx.stats.components[lang] ?? 0) + 1;\n  try {\n    const warn = ({ line: at = 0, message }) => ctx.stats.componentWarnings?.push({ line: line + at, component: lang, message });\n    const html = comp.render(text, { args, uid: () => `am${++ctx.seq}`, ui: ctx.ui, dir: ctx.dir ?? 'ltr', video: ctx.video, warn });\n    // A component's own svg is measured in viewBox units at fixed text sizes, so the whole box takes the factor. Raw svg / html blocks\n    // bypass this function, and a video never scales.\n    return ctx.video ? html : scaleSvgBoxes(html, ctx.scale ?? 1);\n  } catch (err) {\n    if (!(err instanceof ComponentError)) throw err;\n    throw new RenderError(err.message, {\n      line: line + (err.line || 0),\n      component: lang,\n      example: comp.example,\n    });\n  }\n}\n\n// A fence that is not a component is code. In a video the block has no copy button.\nfunction codeBlock(block, ctx) {\n  try {\n    const { html, file, warnings } = renderCode(block, { ...ctx.code, ui: ctx.ui, copy: !ctx.video });\n    if (file && ctx.stats.code) ctx.stats.code.push(file);\n    if (ctx.stats.codeWarnings) ctx.stats.codeWarnings.push(...warnings.map((w) => ({ line: block.line, ...w })));\n    return html;\n  } catch (err) {\n    if (!(err instanceof CodeError)) throw err;\n    throw new RenderError(err.message, { line: block.line + err.line, component: 'code', example: err.example });\n  }\n}\n\n// order: 'ymd' (2026-10-07 22:44) or 'dmy' (7.10.2026 22:44, the way Hebrew readers write a date).\nexport function timestamp(d = new Date(), order = 'ymd') {\n  const p = (n) => String(n).padStart(2, '0');\n  const time = `${p(d.getHours())}:${p(d.getMinutes())}`;\n  if (order === 'dmy') return `${d.getDate()}.${d.getMonth() + 1}.${d.getFullYear()} ${time}`;\n  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${time}`;\n}\n\n// The line at the top of the page, above the title. On a right-to-left page the product name with its version, the time and the star link are each\n// isolated, so the Latin name, the version and the date do not merge into one left-to-right run. The star link is English in\n// every language, like the product name.\nfunction colophon(language) {\n  const repo = 'https://github.com/QingYunA/answer-me-with-html';\n  const link = `<a href=\"${repo}\" target=\"_blank\" rel=\"noopener\">Answer me with HTML</a>`;\n  const star = `<a href=\"${repo}\" target=\"_blank\" rel=\"noopener\">★ Star on GitHub</a>`;\n  const label = esc(language.ui.generated ?? 'Generated by');\n  const time = esc(timestamp(new Date(), language.dateOrder));\n  if (language.dir === 'rtl') return `<p class=\"am-colophon\">${label} <bdi>${link} ${VERSION}</bdi> · <bdi>${time}</bdi> · <bdi>${star}</bdi></p>`;\n  return `<p class=\"am-colophon\">${label} ${link} ${VERSION} · ${time} · ${star}</p>`;\n}\n\n// The colophon opens the page header. It goes in after src/bidi.js has run over the body, since it isolates its own runs. The\n// template's header is the first one in the body: the intro and the panels come after it.\nconst withColophon = (body, language) => body.replace('<header class=\"am-head\">', (head) => `${head}${colophon(language)}`);\n\n// The new-version button and its popover (a native popover, so it opens, closes on Esc and on a click outside with no script). The\n// button starts hidden; src/runtime/update.js shows it where the browser has popovers. withoutUpdateNotice takes both out again.\nfunction updateNotice(ui, update, labelKey) {\n  if (!update) return { button: '', popover: '' };\n  const t = ui.update;\n  // The highlights in the page language, else in English (the labels fall back the same way). `code` spans become <code>.\n  const lines = update.highlights?.[labelKey] ?? update.highlights?.en;\n  const notes = lines\n    ? `<p class=\"am-update-label\">${esc(t.whatsNew)}</p>\\n<ul class=\"am-update-notes\">${lines.map((l) => `<li>${esc(l).replace(/`([^`]+)`/g, '<code>$1</code>')}</li>`).join('')}</ul>\\n`\n    : '';\n  const plain = t.button.replace('{version}', update.latest);\n  const fill = (s) => esc(s).replace('{version}', `<bdi>${esc(update.latest)}</bdi>`).replace('{current}', `<bdi>${esc(update.current)}</bdi>`);\n  // The command is code and reads left to right; the line for the agent is a sentence in the page language.\n  const row = (text, code) => `<div class=\"am-update-row\">${code ? `<code dir=\"ltr\">${esc(text)}</code>` : `<span>${esc(text)}</span>`}<button class=\"am-btn\" type=\"button\" data-am=\"copy-text\" data-text=\"${esc(text)}\" data-done=\"${esc(ui.done)}\">${esc(ui.copyCode)}</button></div>`;\n  return {\n    button: `<button class=\"am-btn am-btn--update\" type=\"button\" data-am=\"update\" popovertarget=\"am-update\" aria-label=\"${esc(plain)}\" hidden>● <span class=\"am-update-text\">${fill(t.button)}</span></button>\\n`,\n    popover: `<div class=\"am-update\" id=\"am-update\" popover>\n<p class=\"am-update-title\">${fill(t.button)}</p>\n<p>${fill(t.current)}</p>\n${notes}<p class=\"am-update-label\">${esc(t.run)}</p>\n${row(update.command, true)}\n<p class=\"am-update-label\">${esc(t.agent)}</p>\n${row(t.agentText, false)}\n<a href=\"https://github.com/QingYunA/answer-me-with-html/releases\" target=\"_blank\" rel=\"noopener\">${esc(t.notes)}</a>\n</div>\n`,\n  };\n}\n\n// The page without its new-version button and popover, for a reader on another device (src/serve.js): the notice is for the person\n// who made the page. Both come before the body, so the first match is the one updateNotice wrote.\nexport function withoutUpdateNotice(html) {\n  return html\n    .replace(/<button class=\"am-btn am-btn--update\"[^]*?<\\/button>\\n/, '')\n    .replace(/<div class=\"am-update\" id=\"am-update\" popover>[^]*?\\n<\\/div>\\n/, '');\n}\n\n// A diagram with change markers carries a count row; only then the page needs the delta styles and script.\nexport const hasDelta = (html) => html.includes('class=\"am-delta-bar\"');\n\n// A chart (src/components/chart.js) needs its own styles, as a formula needs the math ones.\nexport const hasChart = (html) => html.includes('class=\"am-diagram am-chart\"');\n\nfunction lightboxShell(ui, hasDiagrams) {\n  if (!hasDiagrams) return '';\n  return `<div class=\"am-lightbox\" hidden aria-modal=\"true\" role=\"dialog\" aria-label=\"${esc(ui.diagram)}\" data-expand=\"${esc(ui.expand)}\">\n<div class=\"am-lightbox-backdrop\"></div>\n<div class=\"am-lightbox-header\">\n<div class=\"am-lightbox-title\">\n<svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"3\" y1=\"9\" x2=\"21\" y2=\"9\"></line><line x1=\"9\" y1=\"21\" x2=\"9\" y2=\"9\"></line></svg>\n<span class=\"am-lightbox-title-text\"></span>\n</div>\n<div class=\"am-lightbox-actions\">\n<button class=\"am-lightbox-close\" data-action=\"close\" title=\"${esc(ui.close)}\" aria-label=\"${esc(ui.close)}\">✕</button>\n</div>\n</div>\n<div class=\"am-lightbox-stage\">\n<div class=\"am-lightbox-canvas am-diagram\"></div>\n</div>\n</div>\n`;\n}\n\n// Seconds the page waits before it closes its tab; the page shows the countdown (src/runtime/close-after-reply.js).\nconst CLOSE_AFTER_SECONDS = 3;\n\n// The toolbar's text-size buttons. They carry the range from SCALE and start hidden: the runtime reads the numbers off them and\n// reveals them, so a reader without JavaScript gets no button that cannot do anything.\nfunction scaleButtons(ui) {\n  const range = `data-min=\"${SCALE.min}\" data-max=\"${SCALE.max}\" data-step=\"${SCALE.step}\"`;\n  const button = (action, label, text) =>\n    `<button class=\"am-btn\" type=\"button\" data-am=\"${action}\" ${range} aria-label=\"${esc(label)}\" title=\"${esc(label)}\" hidden>${text}</button>`;\n  return `${button('scale-down', ui.scale.down, 'A−')}${button('scale-up', ui.scale.up, 'A+')}`;\n}\n\nfunction shell({ meta, language, body, source, embedded, update, closeAfter, scale }) {\n  const { ui, labelKey } = language;\n  const notice = updateNotice(ui, update, labelKey);\n  const pick = (name, label, values, current) => `<label class=\"am-pick\">${esc(label)}<select data-am=\"${name}\">${values\n    .map(([value, text]) => `<option value=\"${esc(value)}\"${value === current ? ' selected' : ''}>${esc(text)}</option>`).join('')}</select></label>`;\n  const root = { lang: language.htmlLang, dir: language.dir, theme: meta.theme, mode: meta.mode, style: meta.style, scale };\n  // The one inline script, as the browser reads it: the policy pins a hash of exactly this text.\n  const script = `\\n${RUNTIME_JS}${hasDelta(body) ? DELTA_JS : ''}${update ? UPDATE_JS : ''}${closeAfter ? CLOSE_AFTER_JS : ''}`;\n  return `<!doctype html>\n${rootTag(root)}\n<head>\n<meta charset=\"utf-8\">\n${cspMeta([script], { live: true })}\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"generator\" content=\"Answer me with HTML ${VERSION}\">\n<title>${esc(meta.title || 'Answer me with HTML')}</title>\n<style>\n${pageCss(embedded, { diff: body.includes('class=\"am-codeblock am-codeblock--diff\"'), delta: hasDelta(body), rtl: language.dir === 'rtl', math: hasMath(body), chart: hasChart(body), update: Boolean(update), closeAfter, scale })}\n</style>\n</head>\n<body>\n<div class=\"am-toolbar\"${rootCarrierAttrs(root)}>\n${notice.button}${pick('theme', ui.theme, embedded.map((t) => [t.name, t.label[labelKey]]), meta.theme)}\n${pick('mode', ui.modeLabel, Object.entries(ui.mode), meta.mode)}\n${scaleButtons(ui)}\n<button class=\"am-btn am-btn--reply\" type=\"button\" data-am=\"reply\" data-ui=\"${esc(JSON.stringify({ ...ui.reply, done: ui.done, remarks: ui.remark.section, kinds: ui.remark.kinds, ...(closeAfter ? { closeAfter: { seconds: CLOSE_AFTER_SECONDS, ...ui.closeAfter } } : {}) }))}\">${esc(ui.reply.button)}</button>\n<button class=\"am-btn am-btn--remark\" type=\"button\" data-am=\"remark\" data-ui=\"${esc(JSON.stringify(ui.remark))}\">${esc(ui.remark.button)}</button>\n<button class=\"am-btn\" type=\"button\" data-am=\"copy\" data-done=\"${esc(ui.done)}\">${esc(ui.copy)}</button>\n</div>\n${notice.popover}${withColophon(body, language)}\n${lightboxShell(ui, body.includes('class=\"am-diagram'))}${sourceTag(source)}\n<script>${script}</script>\n</body>\n</html>\n`;\n}\n"
    },
    {
      "path": "src/components/flow.js",
      "content": "// Flow / architecture diagram: the model writes only relations (A -> B: label), dagre computes coordinates, this file draws the layout as SVG.\nimport dagre from '@dagrejs/dagre';\nimport { esc, measure, wrap } from '../svg/text.js';\nimport { f, smoothPath, arrowDefs, svgOpen, textLines, diagramLabel, mirrorLayout } from '../svg/shapes.js';\nimport { svgLine } from '../bidi.js';\nimport { ComponentError, contentLines } from './error.js';\nimport { splitMarker, markState, deltaAttr, withDelta, SIGN } from './delta.js';\nimport { DRAWING } from '../themes/type-scale.js';\n\nconst FS = DRAWING.node;\nconst LH = 17;\nconst TEXT_MAX = 150;\nconst EDGE_MAX = 240;\nconst EDGE_FS = DRAWING.edge;\nconst CLUSTER_FS = DRAWING.cluster;\nconst CLUSTER_LABEL_H = 15;\nconst DIRS = new Set(['TB', 'LR', 'BT', 'RL']);\n// Mermaid-trained agents write a literal \\n for a line break. A backslash and an n in a label mean one too.\nconst FORCED_BREAK = /\\\\n/;\n\n// Shape brackets: match longer opening brackets first.\nconst BRACKETS = [\n  { open: '[(', close: ')]', shape: 'db' },\n  { open: '[', close: ']', shape: 'rect' },\n  { open: '(', close: ')', shape: 'round' },\n  { open: '{', close: '}', shape: 'diamond' },\n];\nconst ARROW = /^\\s*(-->|->)\\s*/;\n// Mermaid writes a node as an ID followed by its text in shape brackets, e.g. B{OK?}. flow has no node IDs, so that\n// form splits into two nodes; it is only unambiguous when the ID is also a node of its own. Mermaid always has text in the\n// brackets, so empty ones such as init() are not an ID.\nconst MERMAID_ID = /^([A-Za-z_][\\w-]*)([\\[({]+[^\\])}].*)$/;\n// The flow brackets that mean the same as a Mermaid shape, and the closest one for the shapes flow does not have.\n// Longer openings come first.\nconst MERMAID_SHAPES = [\n  { open: '([', close: '])', write: (text) => `(${text})` },\n  { open: '[[', close: ']]', write: (text) => `[${text}]` },\n  { open: '((', close: '))', write: (text) => `(${text})` },\n  { open: '{{', close: '}}', write: (text) => `[${text}]` },\n  { open: '[/', close: '/]', write: (text) => `[${text}]` },\n  { open: '[\\\\', close: '\\\\]', write: (text) => `[${text}]` },\n  { open: '[(', close: ')]', write: (text) => `[(${text})]` },\n  { open: '[', close: ']', write: (text) => `[${text}]` },\n  { open: '(', close: ')', write: (text) => `(${text})` },\n  { open: '{', close: '}', write: (text) => `{${text}}` },\n];\n\nexport default {\n  name: 'flow',\n  summary: 'Flowchart / architecture diagram (automatic layout)',\n  syntax: `\\`\\`\\`flow [TB|LR|BT|RL]\nA -> B: label                 ← solid line; text after the colon is the edge label\nA -> B: first\\\\nsecond line    ← a literal \\\\n in a node or edge label forces a line break\nA --> C                       ← dashed line\nA -> B -> C                   ← chain\nA -> B & C                    ← fan-out\n(Start)  {Valid?}  [(Database)]  [text with: a colon]   ← rounded / diamond / cylinder / rectangle\n*Key node                     ← * prefix highlights\ngroup Group name: B, C        ← draw a group box around nodes\n\\`\\`\\`\n- The text inside the brackets is the node's identity; later lines can refer to the node by that text alone. The default direction is TB (top to bottom).\n- Mermaid node IDs are not accepted: write the text alone, [Start] rather than A[Start], and refer to it later as Start.\n- Change markers show what a plan adds, removes and changes. A line can start with + (added), - (removed) or ~ (changed), followed by a space:\n\\`\\`\\`flow LR\nClient -> Gateway\n+ Gateway -> [(Cache)]: lookup\n+ Cache -> Service: miss\n- Gateway -> Service\n~ *Service\n\\`\\`\\`\n  - A marker applies to every link on its line. A node is removed when it appears only on - lines, added when it appears only on + lines, and unchanged when it also appears on an unmarked line, even if its links changed. ~ Node on a line without an arrow marks that node as changed.\n  - ~ on a line with an arrow is an error: remove the old link with - and add the new one with +. That is also how a link's label changes. The same link both unmarked and marked is an error too.\n  - + group Name: A, B and - group Name: A, B mark a group box. A group that is not removed and holds only removed nodes is a warning. Markers combine with * and every shape bracket.\n  - The Changes view draws added in the theme's ok color, removed faded with a struck-through label, changed with a warn outline, and each marked node with a +, − or ~ badge. A count row and a Before / Changes / After switch sit under the diagram: Before and After show the diagram as it was and as it will be, plain and without the items that are not in that view.\n  - A line that starts with a marker and a space is always read as a marker. To keep a node name that starts with \"- \", write it in brackets: [- Gateway].`,\n  example: '```flow LR\\n(User) -> Gateway: HTTPS\\nGateway -> Auth & *Service\\nService -> [(Database)]\\ngroup Backend: Auth, Service\\n```',\n  render(text, { args, uid, ui, warn, video, dir: pageDir = 'ltr' }) {\n    const model = parseFlow(text);\n    model.warnings.forEach((w) => warn?.(w));\n    const flowDir = (args.match(/\\b(TB|LR|BT|RL)\\b/i)?.[1] ?? 'TB').toUpperCase();\n    const html = `<figure class=\"am-diagram am-flow\">${layout(model, DIRS.has(flowDir) ? flowDir : 'TB', uid(), ui, pageDir)}</figure>`;\n    return withDelta(html, [...model.nodes.values(), ...model.edges, ...model.groups].map((x) => x.state ?? null), { ui, video });\n  },\n};\n\nexport function parseFlow(text) {\n  const nodes = new Map();\n  const edges = [];\n  const groups = [];\n  // before / after: whether the node exists before and after the change; tilde: a \"~ Node\" line marked it changed.\n  const upsert = (spec, line, mark) => {\n    const prev = nodes.get(spec.id);\n    const seen = { before: mark !== '+', after: mark !== '-', tilde: mark === '~' };\n    if (!prev) nodes.set(spec.id, { ...spec, ...seen, line });\n    else {\n      const merged = { before: prev.before || seen.before, after: prev.after || seen.after, tilde: prev.tilde || seen.tilde };\n      nodes.set(spec.id, { ...prev, ...merged, explicit: prev.explicit || spec.explicit, shape: spec.explicit ? spec.shape : prev.shape, hi: prev.hi || spec.hi });\n    }\n    return spec.id;\n  };\n\n  for (const { text: raw, line } of contentLines(text)) {\n    const { mark, text: t } = splitMarker(raw);\n    const g = t.match(/^group\\s+(.+?)\\s*[:：]\\s*(.+)$/i);\n    if (g) {\n      if (mark === '~') throw new ComponentError('flow: ~ marks a node, not a group. Use + group or - group to add or remove a group box', line);\n      const state = markState(mark);\n      groups.push({ name: g[1], members: g[2].split(/[,，]/).map((s) => s.trim()).filter(Boolean), line, ...(state && { state }) });\n      continue;\n    }\n    const { chain, label } = parseChain(t, line);\n    if (mark === '~' && chain.length > 1) {\n      throw new ComponentError('flow: ~ marks a node, not a link. To change a link, remove the old one and add the new one: \"- A -> B\" then \"+ A -> C\"', line);\n    }\n    const ids = chain.map((step) => ({ ...step, ids: step.nodes.map((n) => upsert(n, line, mark)) }));\n    for (let k = 1; k < ids.length; k++) {\n      const isLast = k === ids.length - 1;\n      for (const from of ids[k - 1].ids) {\n        for (const to of ids[k].ids) {\n          const state = markState(mark);\n          edges.push({ from, to, dashed: ids[k].arrow === '-->', label: isLast ? label : '', line, ...(state && { state }) });\n        }\n      }\n    }\n  }\n  if (!nodes.size) throw new ComponentError('flow needs at least one node', 1);\n  checkMermaidIds(nodes);\n  for (const grp of groups) {\n    const missing = grp.members.filter((m) => !nodes.has(m));\n    if (missing.length) throw new ComponentError(`group ${grp.name} refers to nodes that do not exist: ${missing.join(', ')}`, grp.line);\n  }\n  checkLinks(edges);\n  const settled = new Map([...nodes].map(([id, n]) => {\n    const state = nodeState(n);\n    return [id, state ? { ...n, state } : n];\n  }));\n  return { nodes: settled, edges, groups, warnings: [...groupWarnings(groups, settled), ...mermaidIdWarnings(settled)] };\n}\n\n// A node written as an ID plus shape brackets, while that ID is also a node of its own, is a Mermaid node ID that\n// this component split in two. The message shows the line rewritten with the text alone.\nfunction checkMermaidIds(nodes) {\n  for (const n of nodes.values()) {\n    const m = n.explicit ? null : n.label.match(MERMAID_ID);\n    if (!m) continue;\n    const id = nodes.get(m[1]);\n    // A change marker can put the label and its ID on opposite sides of the change, and then no view draws the split.\n    if (!id || !((n.before && id.before) || (n.after && id.after))) continue;\n    throw new ComponentError(\n      `\"${m[1]}\" is a node on its own and also the ID of \"${n.label}\"; this block has no node IDs, so write the text alone${rewriteOf(m[2])}`,\n      n.line,\n    );\n  }\n}\n\n// A Mermaid ID that no split can prove is still drawn with the ID inside the box, so it gets a warning; the page\n// still renders.\nfunction mermaidIdWarnings(nodes) {\n  const notes = [];\n  for (const n of nodes.values()) {\n    const m = n.explicit ? null : n.label.match(MERMAID_ID);\n    if (!m) continue;\n    notes.push({\n      line: n.line,\n      message: `\"${n.label}\" looks like a Mermaid node ID with its text; this block has no node IDs, so the box shows \"${n.label}\". If you meant the text, write it alone${rewriteOf(m[2])}`,\n    });\n  }\n  return notes;\n}\n\n// How to write the node instead: the flow brackets that mean the same as the Mermaid shape. A bracket the parser cut\n// before its closing one (a colon ends the text) leaves no text to quote, so the message only names the brackets.\nfunction rewriteOf(rest) {\n  const shape = MERMAID_SHAPES.find((s) => rest.startsWith(s.open));\n  const close = shape ? rest.indexOf(shape.close, shape.open.length) : -1;\n  if (close === -1) return ' in brackets, colon included';\n  return `: ${shape.write(rest.slice(shape.open.length, close).trim())}`;\n}\n\n// Removed when the node exists only before, added when only after; on both sides it is unchanged unless a \"~ Node\" line marked it.\nfunction nodeState({ before, after, tilde }) {\n  if (before && !after) return 'removed';\n  if (after && !before) return 'added';\n  return tilde ? 'changed' : null;\n}\n\n// A link that is written both unmarked and marked says two things about the same link.\nfunction checkLinks(edges) {\n  const key = (e) => `${e.from}\\u0000${e.to}`;\n  for (const e of edges.filter((x) => x.state)) {\n    const plain = edges.find((x) => !x.state && key(x) === key(e));\n    if (plain) throw new ComponentError(`flow: the link ${e.from} -> ${e.to} is written unmarked on line ${plain.line} and as ${e.state === 'added' ? '+' : '-'} here. Mark every line of that link, or none`, e.line);\n  }\n}\n\n// A group that stays after the change but holds only removed nodes would be an empty box in the After view.\nfunction groupWarnings(groups, nodes) {\n  return groups\n    .filter((g) => g.state !== 'removed' && g.members.every((m) => nodes.get(m).state === 'removed'))\n    .map((g) => ({ line: g.line, message: `group ${g.name} holds only removed nodes and would be an empty box after the change. Mark it with \"- group ${g.name}: ${g.members.join(', ')}\"` }));\n}\n\n// One line = node groups (separated by &) joined by arrows, optionally ending with \": label\".\nfunction parseChain(t, line) {\n  const chain = [];\n  let pos = 0;\n  let arrow = null;\n  for (;;) {\n    const group = [];\n    for (;;) {\n      const { node, end } = parseNode(t, pos, line);\n      group.push(node);\n      pos = end;\n      const amp = t.slice(pos).match(/^\\s*&\\s*/);\n      if (!amp) break;\n      pos += amp[0].length;\n    }\n    chain.push({ arrow, nodes: group });\n    const a = t.slice(pos).match(ARROW);\n    if (!a) break;\n    arrow = a[1];\n    pos += a[0].length;\n  }\n  const rest = t.slice(pos).trim();\n  if (rest && !/^[:：]/.test(rest)) {\n    throw new ComponentError(`flow cannot parse \"${t}\". Write a link as A -> B: label`, line);\n  }\n  return { chain, label: rest.replace(/^[:：]\\s*/, '') };\n}\n\nfunction parseNode(t, start, line) {\n  let pos = start + t.slice(start).match(/^\\s*/)[0].length;\n  const hi = t[pos] === '*';\n  if (hi) pos++;\n  const bracket = BRACKETS.find((b) => t.startsWith(b.open, pos));\n  let label;\n  let end;\n  if (bracket) {\n    const close = t.indexOf(bracket.close, pos + bracket.open.length);\n    if (close === -1) throw new ComponentError(`flow: unclosed shape bracket, missing ${bracket.close}`, line);\n    label = t.slice(pos + bracket.open.length, close).trim();\n    end = close + bracket.close.length;\n  } else {\n    const m = t.slice(pos).match(/^(.*?)(?=\\s*(?:-->|->|&|[:：]|$))/);\n    label = m[1].trim();\n    end = pos + m[0].length;\n  }\n  if (!label) throw new ComponentError(`flow has an empty node: \"${t}\"`, line);\n  return { node: { id: label, label, shape: bracket?.shape ?? 'rect', explicit: Boolean(bracket), hi }, end };\n}\n\n// A literal \\n forces a line break; each forced line still wraps by width as before.\nfunction labelLines(label, maxWidth, size) {\n  return String(label).split(FORCED_BREAK).flatMap((part) => wrap(part, maxWidth, size));\n}\n\n// Edge labels are not wrapped unless they carry a forced break: that keeps a long label as it was drawn before.\nfunction edgeText(label) {\n  const parts = String(label).split(FORCED_BREAK);\n  const lines = parts.length > 1 ? parts.flatMap((part) => wrap(part, EDGE_MAX, EDGE_FS)) : [String(label)];\n  return {\n    lines,\n    width: Math.max(...lines.map((line) => measure(line, EDGE_FS))) + 10,\n    height: lines.length === 1 ? 18 : lines.length * LH,\n  };\n}\n\nfunction nodeSize(node) {\n  const lines = labelLines(node.label, TEXT_MAX, FS);\n  const tw = Math.max(...lines.map((l) => measure(l, FS)));\n  const th = lines.length * LH;\n  const w = Math.max(tw + 28, 64);\n  const h = th + 18;\n  const size = {\n    rect: [w, h],\n    round: [w + 12, h],\n    diamond: [(tw + 28) * 1.5, h * 1.6],\n    db: [w, h + 14],\n  }[node.shape];\n  return { lines, width: size[0], height: size[1] };\n}\n\nconst nodeKey = (i) => `n${i}`;\nconst gkey = (i) => `g${i}`;\nconst reserveKey = (i) => `r${i}`;\n\n// Run dagre. reserve maps each group whose name found no free place in the first layout to the side it gets room on:\n// in TB and BT a label-sized node above the group's first members, which dagre keeps clear of every edge passing by;\n// in LR and RL a strip inserted under the box's top edge, or above its bottom edge when an edge crosses the top one\n// (edges there mostly run sideways, so a strip stays empty).\nfunction runLayout({ nodes, edges, groups }, rankdir, rtl, widths, reserve) {\n  const g = new dagre.graphlib.Graph({ compound: groups.length > 0, multigraph: true });\n  g.setGraph({ rankdir, nodesep: 36, ranksep: 46, marginx: 14, marginy: groups.length ? 26 : 14 });\n  g.setDefaultEdgeLabel(() => ({}));\n  // dagre reserves ids such as \"\\x00\" internally; nodes and groups always get internal numbers, so no user-written name can collide.\n  const key = new Map([...nodes.keys()].map((name, i) => [name, nodeKey(i)]));\n  const sizes = new Map();\n  for (const n of nodes.values()) {\n    const s = nodeSize(n);\n    sizes.set(n.id, s);\n    g.setNode(key.get(n.id), { width: s.width, height: s.height });\n  }\n  const vertical = rankdir === 'TB' || rankdir === 'BT';\n  groups.forEach((grp, i) => {\n    g.setNode(gkey(i), { label: grp.name });\n    grp.members.forEach((m) => g.setParent(key.get(m), gkey(i)));\n    if (!reserve.has(i) || !vertical) return;\n    g.setNode(reserveKey(i), { width: widths[i] + 4, height: CLUSTER_LABEL_H });\n    g.setParent(reserveKey(i), gkey(i));\n    // Seen from the top of the drawing (BT reverses every edge): the room goes above the group's first members, those no other\n    // member points to, and below every node outside the group that points to one of them, so their edges pass beside it.\n    const down = edges.map((e) => (rankdir === 'TB' ? [e.from, e.to] : [e.to, e.from]));\n    const link = (a, b, name) => (rankdir === 'TB' ? g.setEdge(a, b, {}, name) : g.setEdge(b, a, {}, name));\n    const inside = new Set(grp.members);\n    const first = grp.members.filter((m) => !down.some(([a, b]) => b === m && a !== m && inside.has(a)));\n    (first.length ? first : grp.members.slice(0, 1)).forEach((m, k) => {\n      link(reserveKey(i), key.get(m), `r${i}-${k}`);\n      down.forEach(([a, b], j) => {\n        if (b === m && !inside.has(a)) link(key.get(a), reserveKey(i), `r${i}-${k}-${j}`);\n      });\n    });\n  });\n  edges.forEach((e, i) => {\n    const size = e.label ? edgeText(e.label) : null;\n    // Dagre reserves 2px more than the drawn label box, as it always did.\n    const label = size ? { label: e.label, width: size.width + 2, height: size.height, labelpos: 'c' } : {};\n    g.setEdge(key.get(e.from), key.get(e.to), label, `e${i}`);\n  });\n  dagre.layout(g);\n  // A right-to-left page mirrors the finished layout: every direction then reads from the right, and LR runs right to left.\n  if (rtl) mirrorLayout(g);\n  if (!vertical) {\n    for (const [i, side] of reserve) {\n      const c = g.node(gkey(i));\n      insertStrip(g, side === 'top' ? top(c) + 2 : top(c) + c.height - 2, CLUSTER_LABEL_H + 3);\n    }\n  }\n  fitEdges(g);\n  return { g, key, sizes };\n}\n\n// dagre sizes the drawing to its nodes, boxes and edge labels, not to edge points: a long edge routed around the outside of the\n// layout can run past the margin, or past the edge of the svg where it is cut off. Grow the drawing so every point of a drawn\n// edge keeps the margin too. The edges that only hold room for a group name are not drawn and do not count.\nfunction fitEdges(g) {\n  const graph = g.graph();\n  const points = g.edges().filter((e) => e.name.startsWith('e')).flatMap((e) => g.edge(e).points);\n  if (!points.length) return;\n  const xs = points.map((p) => p.x);\n  const ys = points.map((p) => p.y);\n  const up = graph.marginy - Math.min(...ys);\n  if (up > 0) insertStrip(g, -Infinity, up);\n  const left = graph.marginx - Math.min(...xs);\n  if (left > 0) shiftRight(g, left);\n  graph.width = Math.max(graph.width, Math.max(...xs) + Math.max(left, 0) + graph.marginx);\n  graph.height = Math.max(graph.height, Math.max(...ys) + Math.max(up, 0) + graph.marginy);\n}\n\n// Move the whole drawing right by d: nodes, boxes, edge points and edge labels. The drawing gets d wider.\nfunction shiftRight(g, d) {\n  for (const v of g.nodes()) g.node(v).x += d;\n  for (const e of g.edges()) {\n    const edge = g.edge(e);\n    edge.points = edge.points.map((p) => ({ ...p, x: p.x + d }));\n    if (edge.x !== undefined) edge.x += d;\n  }\n  g.graph().width += d;\n}\n\n// Push everything below the line y down by d: nodes, edge points, edge labels, and the boxes that start below it; a box the line\n// cuts through grows by d. The drawing gets d taller.\nfunction insertStrip(g, y, d) {\n  for (const v of g.nodes()) {\n    const n = g.node(v);\n    if (v.startsWith('g') && top(n) < y && top(n) + n.height > y) {\n      n.height += d;\n      n.y += d / 2;\n    } else if (n.y > y) n.y += d;\n  }\n  for (const e of g.edges()) {\n    const edge = g.edge(e);\n    edge.points = edge.points.map((p) => (p.y > y ? { ...p, y: p.y + d } : p));\n    if (edge.y !== undefined && edge.y > y) edge.y += d;\n  }\n  g.graph().height += d;\n}\n\nconst top = (n) => n.y - n.height / 2;\n\n// Where each group name goes: [x, baseline] of its text, or null when no place along the top of the box is free of nodes, edges,\n// edge labels and other group names. The name starts in the corner where reading starts (top left, or top right on a right-to-left\n// page) and slides toward the other corner past whatever is in the way.\nfunction placeLabels({ g, key, sizes }, { nodes, edges, groups }, widths, rtl, reserve) {\n  const boxes = [];\n  for (const n of nodes.values()) {\n    const { x, y } = g.node(key.get(n.id));\n    const { width: w, height: h } = sizes.get(n.id);\n    boxes.push([x - w / 2, y - h / 2, x + w / 2, y + h / 2]);\n  }\n  const segments = [];\n  edges.forEach((e, i) => {\n    const data = g.edge({ v: key.get(e.from), w: key.get(e.to), name: `e${i}` });\n    const pts = data.points;\n    for (let k = 1; k < pts.length; k++) segments.push([pts[k - 1], pts[k]]);\n    if (e.label) {\n      const { width: w, height: h } = edgeText(e.label);\n      boxes.push([data.x - w / 2, data.y - h / 2, data.x + w / 2, data.y + h / 2]);\n    }\n  });\n  return groups.map((grp, i) => {\n    const c = g.node(gkey(i));\n    const left = c.x - c.width / 2;\n    const right = left + c.width;\n    const w = widths[i];\n    const own = grp.state ? [[rtl ? left - 8 : right - 8, top(c) - 8, rtl ? left + 8 : right + 8, top(c) + 8]] : [];\n    // A name needs air around it: an edge label right beside it would read as one phrase with it.\n    const free = (x0, y0, y1) => {\n      const box = [x0 - 5, y0 - 2, x0 + w + 5, y1 + 2];\n      const wide = [x0 - 10, y0 - 2, x0 + w + 10, y1 + 2];\n      return ![...boxes, ...own].some((b) => overlaps(wide, b)) && !segments.some(([p, q]) => segmentHits(p, q, box));\n    };\n    // First just under the top edge, then on the room reserved for it: a node, or a strip along the bottom edge.\n    const room = g.hasNode(reserveKey(i)) ? g.node(reserveKey(i)) : null;\n    const baselines = reserve.get(i) === 'bottom' ? [top(c) + c.height - 6] : room ? [top(c) + 14, room.y + 4] : [top(c) + 14];\n    for (const baseline of baselines) {\n      const [y0, y1] = [baseline - 11, baseline + 4];\n      for (let s = 0; s <= Math.max(0, c.width - 16 - w); s += 4) {\n        const x0 = rtl ? right - 8 - w - s : left